/* systemsvc.MenuMapper.insertMenu(메뉴 등록) */
INSERT INTO menus (
    parent_menu_id
    ,menu_cd
    ,menu_nm
    ,menu_type
    ,path
    ,component
    ,icon
    ,depth
    ,sort_seq
    ,visible_yn
    ,use_yn
    ,remark
    ,created_by
    ,created_at
    ,updated_by
    ,updated_at
)
VALUES (
    #{request.data.parentMenuId}
    ,#{request.data.menuCd}
    ,#{request.data.menuNm}
    ,COALESCE(#{request.data.menuType}, 'MENU')
    ,#{request.data.path}
    ,#{request.data.component}
    ,#{request.data.icon}
    ,COALESCE(#{request.data.depth}, 1)
    ,COALESCE(#{request.data.sortSeq}, 0)
    ,COALESCE(#{request.data.visibleYn}, 'Y')
    ,COALESCE(#{request.data.useYn}, 'Y')
    ,#{request.data.remark}
    ,#{createdBy}
    ,current_timestamp
    ,#{createdBy}
    ,current_timestamp
)

mapper.update:

/* systemsvc.MenuMapper.updateMenu(메뉴 수정) */
UPDATE menus
SET parent_menu_id = #{request.data.parentMenuId}
    ,menu_nm = #{request.data.menuNm}
    ,menu_type = COALESCE(#{request.data.menuType}, menu_type)
    ,path = #{request.data.path}
    ,component = #{request.data.component}
    ,icon = #{request.data.icon}
    ,depth = COALESCE(#{request.data.depth}, depth)
    ,sort_seq = COALESCE(#{request.data.sortSeq}, sort_seq)
    ,visible_yn = COALESCE(#{request.data.visibleYn}, visible_yn)
    ,use_yn = COALESCE(#{request.data.useYn}, use_yn)
    ,remark = #{request.data.remark}
    ,updated_by = #{updatedBy}
    ,updated_at = current_timestamp
WHERE menu_id = #{menuId}

