/* systemsvc.MenuMapper.updateReferenceDataVersion(기준정보 최신 버전 갱신) */
UPDATE reference_data_versions
SET version_no = CONCAT(
        split_part(version_no, '.', 1),
        '.',
        split_part(version_no, '.', 2),
        '.',
        (COALESCE(NULLIF(split_part(version_no, '.', 3), ''), '0')::integer + 1)::text
    )
    ,last_changed_at = current_timestamp
    ,last_changed_by = #{changedBy}
    ,remark = #{remark}
    ,updated_at = current_timestamp
    ,updated_by = #{changedBy}
WHERE ref_type = #{refType}
